test.describe('[Blocked] US020 test cases that cannot run on this environment', () => {
  for (const item of blocked) {
    test(`${item.tc} — ${item.title}`, async ({ reconApi }) => {
      let reason: string = REASONS[item.reason];
      if (WAITS_FOR_DATA.includes(item.reason)) {
        const { groups, documents } = await readDevData(reconApi);
        if (groups + documents > 0) {
          reason = `Data now exists on dev (${groups} group(s), ${documents} ungrouped document(s) in ${currentPeriod()}) — this case can be scripted now. Was: ${reason}`;
        }
      }
      await skipTc(item.tc, item.priority, [...TAGS, item.category.toLowerCase()], `Expected: ${item.description}`, reason);
    });
  }
});
